SET TIME ZONE 'UTC';
-- Isolated serialization fixture: index triggers create operational update clocks.
-- Search never exposes or changes this bookkeeping clock; fix it for raw text comparison.
UPDATE search_documents SET updated_at='2001-01-01Z';
SELECT ('00000000-0000-0000-0000-'||lpad((40000+r)::text,12,'0'))::uuid,
'00000000-0000-0000-0000-000000000010',
CASE WHEN r<=6 THEN '00000000-0000-0000-0000-000000000100'::uuid ELSE '00000000-0000-0000-0000-000000000101'::uuid END,
CASE WHEN r<=6 AND r%2=0 THEN '00000000-0000-0000-0000-000000000200'::uuid END,
'00000000-0000-0000-0000-000000000002',E'body 日本語 é😀 " <>\n'||r::text,
CASE WHEN r=1 THEN 3 ELSE 1 END,'2024-04-02Z'::timestamptz+r*interval '1 day',CASE WHEN r=1 THEN '2024-04-20 01:02:03.123456Z'::timestamptz END
FROM generate_series(1,8)r;
SELECT '00000000-0000-0000-0000-000000040001',r,CASE WHEN r=3 THEN E'body 日本語 é😀 " <>\n1' ELSE 'previous '||r::text END,
CASE r WHEN 1 THEN 'historic' WHEN 2 THEN 'mcp' ELSE 'api' END,CASE WHEN r=2 THEN 'client é' END,
'2024-04-03Z'::timestamptz+r*interval '1 day' FROM generate_series(1,3)r;
UPDATE search_documents SET updated_at='2001-01-01Z';
-- Cover every indexed kind through the unchanged production indexing triggers.
UPDATE search_documents SET updated_at='2001-01-01Z';
