INSERT INTO config_revisions(project_id,kind,revision,content,created_by,created_at) SELECT '00000000-0000-0000-0000-000000000010','science',r,jsonb_build_object('metrics',jsonb_build_array(jsonb_build_object('key','score','splits',jsonb_build_array('test','train'),'dimensions',jsonb_build_array(jsonb_build_object('name','lang'),jsonb_build_object('name','size')),'unit','ratio','direction','maximize','aggregation',CASE r WHEN 1 THEN 'mean' WHEN 2 THEN 'sum' ELSE 'median' END),jsonb_build_object('key','empty_metric','splits',jsonb_build_array('test'),'dimensions','[]'::jsonb)),'baselines',jsonb_build_array(jsonb_build_object('id','fixture','revision',r,'description','é')),'hypothesis_fields',jsonb_build_object('properties',jsonb_build_object('cohort','{}'::jsonb))), '00000000-0000-0000-0000-000000000001','2001-01-01Z' FROM generate_series(1,3)r;
INSERT INTO tracks(id,project_id,slug,title,created_by,created_at,updated_at) VALUES('00000000-0000-0000-0000-000000000030','00000000-0000-0000-0000-000000000010','alpha','Alpha','00000000-0000-0000-0000-000000000001','2001-01-01Z','2001-01-01Z'),('00000000-0000-0000-0000-000000000031','00000000-0000-0000-0000-000000000010','beta','Beta','00000000-0000-0000-0000-000000000001','2001-01-01Z','2001-01-01Z');
INSERT INTO hypotheses(id,project_id,number,track_id,state,title,created_by_user,approved_revision,approved_at,origin,source_ref,imported,created_at,updated_at) SELECT ('00000000-0000-0000-0000-'||lpad((100+i)::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000010',i+1,('00000000-0000-0000-0000-'||lpad((30+i%2)::text,12,'0'))::uuid,'promoted','Hypothesis '||i,'00000000-0000-0000-0000-000000000002',1,'2001-01-01Z',CASE WHEN i>=7 THEN 'imported' ELSE 'live' END,CASE WHEN i>=7 THEN 'history:fixture' END,CASE WHEN i>=7 THEN '{}'::jsonb END,'2001-01-01Z','2001-01-01Z' FROM generate_series(0,9)i;
INSERT INTO hypothesis_revisions(hypothesis_id,revision,content,science_revision,author_user,via_channel,origin,source_ref,created_at) SELECT id,1,jsonb_build_object('project_fields',jsonb_build_object('cohort',CASE WHEN number%2=0 THEN 'é' ELSE 'first' END),'control',jsonb_build_object('repo','alpha','commit','a')),1+(number-1)%3,'00000000-0000-0000-0000-000000000002','historic',origin,source_ref,'2001-01-01Z' FROM hypotheses;
INSERT INTO attempts(id,project_id,hypothesis_id,sequence,state,hypothesis_revision,science_revision,track_id,claimed_by_user,via_channel,lease_generation,claimed_at,submitted_at,finished_at,origin,source_ref,imported) SELECT ('00000000-0000-0000-0000-'||lpad((199+number)::text,12,'0'))::uuid,project_id,id,1,CASE WHEN number IN(6,7,10) THEN 'failed' WHEN origin='imported' THEN 'unreviewed' ELSE 'promoted' END,1,1+(number-1)%3,track_id,created_by_user,'historic',1,'2024-03-10 08:00Z','2024-03-10 09:00Z',CASE WHEN number=7 THEN NULL ELSE '2024-03-10 10:00Z'::timestamptz END,origin,source_ref,imported FROM hypotheses;
INSERT INTO phase_outputs(id,project_id,attempt_id,stage,status,revision,front_matter,sha256,producer_user,via_channel,created_at,origin,source_ref) SELECT ('00000000-0000-0000-0000-'||lpad((1000+(h.number-1)*10+(s.stage='tester')::int)::text,12,'0'))::uuid,h.project_id,a.id,s.stage,'completed',1,jsonb_build_object('measurements',(SELECT jsonb_agg(jsonb_build_object('metric','score','split','test','dimensions',d.dimensions,'value',CASE WHEN d.n=2 THEN NULL ELSE h.number-0.5+d.n END,'missing_reason',CASE WHEN d.n=2 THEN 'unavailable' END,'sample_count',CASE d.n WHEN 0 THEN '123.4500' WHEN 1 THEN '-0.000' WHEN 2 THEN '0.000000000123' ELSE '99999999999999999999.00100' END,'unit','ratio','direction','maximize','control_value',0.2,'uncertainty',jsonb_build_object('method','bootstrap','lower',0.1,'upper',0.9)) || CASE WHEN a.origin='imported' THEN jsonb_build_object('authority',CASE WHEN h.number=8 THEN 'imported_artifact' ELSE 'imported_transcribed' END,'source','history#/score') ELSE '{}'::jsonb END ORDER BY d.n) FROM (VALUES(0,'{}'::jsonb),(1,'{"lang":"en"}'::jsonb),(2,'{"lang":"fr"}'::jsonb),(3,'{"lang":"fr","size":"large"}'::jsonb))d(n,dimensions))),repeat('0',64),CASE WHEN a.origin='live' THEN h.created_by_user END,'historic','2024-03-10 09:30Z',a.origin,a.source_ref FROM hypotheses h JOIN attempts a ON a.hypothesis_id=h.id CROSS JOIN (VALUES('agent'),('tester'))s(stage) WHERE a.state<>'failed' AND (a.origin='live' OR s.stage='tester') ORDER BY h.number,s.stage;
INSERT INTO phase_outputs(id,project_id,attempt_id,stage,status,revision,front_matter,sha256,producer_user,via_channel,created_at) VALUES('00000000-0000-0000-0000-000000001012','00000000-0000-0000-0000-000000000010','00000000-0000-0000-0000-000000000201','tester','failed',2,'{}',repeat('0',64),'00000000-0000-0000-0000-000000000002','historic','2024-03-10 09:45Z');
INSERT INTO phase_outputs(id,project_id,attempt_id,stage,status,revision,front_matter,sha256,via_channel,created_at) SELECT ('00000000-0000-0000-0000-'||lpad((2000+(h.number-1)*10+r)::text,12,'0'))::uuid,h.project_id,a.id,'evaluator',CASE r WHEN 1 THEN 'completed' ELSE 'failed' END,r,jsonb_build_object('assessment',jsonb_build_object('verdict','pass','policy_revision','v1','comparisons',jsonb_build_array(jsonb_build_object('metric','score','split','test','dimensions','{}'::jsonb,'value',h.number-0.5,'source','tester','reference',jsonb_build_object('value',0.75,'label','baseline','kind','baseline','ref','fixture'))))),repeat('0',64),'system','2024-03-10 10:00Z' FROM hypotheses h JOIN attempts a ON a.hypothesis_id=h.id CROSS JOIN generate_series(1,2)r WHERE a.origin='live' AND a.state<>'failed' ORDER BY h.number,r;
